def save_bank(bank: dict, bank_path: Path) -> None:
    #
    # ensure_ascii=False keeps accents readable.
    #
    bank_path.write_text(json.dumps(bank, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def load_bank(bank_path: Path) -> dict:
    #
    # json.loads raises on malformed JSON; letting it crash is fine, Python
    # prints the line and column of the problem.
    #
    bank = json.loads(bank_path.read_text(encoding="utf-8"))
    missing_keys = [key for key in DEFAULT_BANK.keys() if key not in bank]
    if missing_keys:
        raise ValueError(f"{bank_path}: missing keys: {', '.join(missing_keys)}")
    bullets = []
    for role in bank["roles"]:
        role.setdefault("company", "")
        role.setdefault("dates", "")
        bullets.extend(role["bullets"])
    for free_entry in bank["free"]:
        free_entry.setdefault("attach_to", "")
    bullets.extend(bank["free"])
    seen_ids = set()
    for bullet in bullets:
        if not bullet["id"] or bullet["id"] in seen_ids:
            raise ValueError(f"{bank_path}: id '{bullet['id']}' is empty or used twice")
        seen_ids.add(bullet["id"])
    return bank


if not BANK_PATH.exists():
    save_bank(DEFAULT_BANK, BANK_PATH)
    print(f"No {BANK_PATH} found: wrote a sample bank there. Edit it with your own details.")
