# 3. JOB SEARCH (jobs come from job_sources.py, already in the common shape)
# ---------------------------------------------------------------------

#
# Probabilmente converrà gestire l'unicità dei risultati prima di questa funzione, 
# nella fase di scaricamento dei dati, in modo da non dover controllare per i duplicati ad ogni ricerca.
# - tbax, 9-10-26
#
def search_jobs(jobs: list[dict], keyword: str) -> list[dict]:
    #
    # Filter locally, the same way for every backend (Remotive's server-side
    # search, for one, is unreliable).
    #
    words = [w for w in keyword.lower().split() if w]
    results = []
    for job in jobs:
        title = job["title"].lower()
        tags = " ".join(job["tags"]).lower()
        score = 3 * sum(w in title for w in words) + sum(w in tags for w in words)
        if score:
            results.append((score, job))
    if not results:  # fall back to jobs whose description has every word
        for job in jobs:
            desc = job["description"].lower()
            if words and all(w in desc for w in words):
                results.append((1, job))
    results.sort(key=lambda x: (x[0], x[1]["published"]), reverse=True)  # best score, then newest
    return [job for _, job in results]

