#
# Dopo aver definito la struttura, bisognerà implementare una constrained grammar generation per il json.
# - tbax, 9-10-26
#
def extract_requirements(job_text: str) -> list[str]:
    prompt = (
        "Read the job posting below and list ALL the skills, tools or qualifications "
        "it asks for, most important first.\n"
        'Output ONLY a JSON array of short strings (1-4 words each), for example: '
        '["SQL", "stakeholder management"]\n\n'
        f"JOB POSTING:\n{job_text[:JD_CHAR_LIMIT]}"
    )
    raw = get_no_history_llm_response(prompt, 400)  # room for a long list; a cut-off list loses its tail
    items = []
    array_start = raw.find("[")
    array_end = raw.find("]", array_start)
    if array_start != -1 and array_end != -1:
        #
        # Splitting on double quotes leaves the quoted strings at the odd
        # positions. This replaces json.loads, so malformed JSON from the
        # small model needs no exception handling.
        #
        items = raw[array_start:array_end].split('"')[1::2]
    if not items:  # small models sometimes answer with a list instead of JSON
        items = [line.strip().lstrip(LIST_MARKER_CHARACTERS).rstrip(LIST_TRAILING_CHARACTERS) for line in raw.splitlines()]
    requirements, seen = [], set()
    for item in items:
        item = str(item).strip()
        if 1 < len(item) <= 40 and item.lower() not in seen:
            seen.add(item.lower())
            requirements.append(item)
    return requirements


def all_bullets(bank: dict) -> list[dict]:
    bullets = []
    for role in bank["roles"]:
        bullets.extend(role["bullets"])
    bullets.extend(bank["free"])
    return bullets


def next_free_id(bank: dict) -> str:
    used_ids = {bullet["id"] for bullet in all_bullets(bank)}
    number = len(bank["free"]) + 1
    while f"f{number}" in used_ids:
        number += 1
    return f"f{number}"


def skill_listed(requirement: str, skills: list[str]) -> bool:
    req = requirement.lower()
    return any(req in s.lower() or (len(s) > 2 and s.lower().split(" (")[0] in req) for s in skills)


def words_in_text(requirement: str, text: str) -> bool:
    #
    # True when every word of the requirement appears in text. Words match by
    # their first 4 letters, so "dashboard" finds "dashboards".
    #
    text_words = [w.strip(VERDICT_PUNCTUATION) for w in text.lower().split()]
    for word in requirement.lower().split():
        word = word.strip(VERDICT_PUNCTUATION)
        if word and not any(t.startswith(word[:4]) for t in text_words):
            return False
    return True


def parse_verdict(raw: str) -> tuple[str, str]:
    #
    # Reads "YES b2", "PARTIAL: b4" or "NO" from the model's reply. Returns the
    # first verdict word and the word right after it (the cited id, or "").
    #
    words = []
    for word in raw.upper().replace(":", " ").split():
        cleaned_word = word.strip(VERDICT_PUNCTUATION)
        if cleaned_word:
            words.append(cleaned_word)
    for position, word in enumerate(words):
        if word in VERDICT_WORDS:
            cited_id = words[position + 1] if position + 1 < len(words) else ""
            return word, cited_id
    return "", ""


def check_requirement(requirement: str, bullets: list[dict], skills: list[str]) -> tuple[str, str]:
    #
    # Returns (status, bullet_id); status is demonstrated / partial / missing
    # and bullet_id is an empty string when no bullet matches.
    #
    for b in bullets:  # exact wording or tagged skill already present: no LLM needed
        wording_in_text = requirement.lower() in b["text"].lower()
        tagged_skill = requirement.lower() == b.get("skill", "").lower()
        if wording_in_text or tagged_skill:
            return "demonstrated", b["id"]

    statements = "\n".join(f"{b['id']}: {b['text']}" for b in bullets)
    prompt = (
        f"Job requirement: {requirement}\n\n"
        f"Candidate statements:\n{statements}\n\n"
        "Decide whether ONE statement above is direct proof that the candidate has this exact requirement.\n"
        "Rules:\n"
        "- A tool or technology only counts if the statement names that same tool. "
        "A similar tool is NOT a match (Tableau is not Power BI, Excel is not SQL).\n"
        "- A soft skill or task only counts if the statement describes the candidate doing it. "
        "Being in the same general area (dashboards, data) is NOT a match.\n"
        "- Most requirements are NOT proven. Only answer YES when you can point at the words in the statement.\n"
        "Reply with ONE line only, in one of these formats:\n"
        "YES <statement id>      (the statement itself shows it)\n"
        "PARTIAL <statement id>  (related, but does not show it)\n"
        "NO                      (nothing shows it)\n"
        "If unsure, answer NO."
    )
    verdict, cited_id = parse_verdict(get_no_history_llm_response(prompt, 12))
    valid_ids = {b["id"].lower(): b["id"] for b in bullets}
    if verdict in ("YES", "PARTIAL") and cited_id.lower() in valid_ids:
        bullet_id = valid_ids[cited_id.lower()]
        cited_text = next(b["text"] for b in bullets if b["id"] == bullet_id)
        # a small model says YES too easily: the cited statement must contain every word of the requirement
        if verdict == "YES" and words_in_text(requirement, cited_text):
            return "demonstrated", bullet_id
        return "partial", bullet_id
    if skill_listed(requirement, skills):
        return "partial", ""  # listed as a skill, but no experience shows it
    return "missing", ""


def make_question(row: dict, lookup: dict) -> str:
    req = row["requirement"]
    if row["status"] == "missing":
        return (f"The job asks for '{req}'. Have you used it anywhere (a course, project, job "
                "or volunteering)? If yes, describe one concrete example.")
    if row["bullet"]:
        return (f"'{req}' is only partly shown by: \"{lookup[row['bullet']]}\". "
                f"What exactly did you do that shows {req}?")
    return (f"You list '{req}' as a skill, but no experience shows it. "
            "Where did you use it, and what did you produce?")


def analyze_gaps(bank: dict, requirements: list[str]) -> list[dict]:
    bullets = all_bullets(bank)
    lookup = {b["id"]: b["text"] for b in bullets}
    rows = []
    for req in requirements:
        status, bullet_id = check_requirement(req, bullets, bank["skills"])
        row = {"requirement": req, "status": status, "bullet": bullet_id}
        row["evidence"] = lookup.get(bullet_id, "")
        row["question"] = "" if status == "demonstrated" else make_question(row, lookup)
        rows.append(row)
    return rows


def add_answer(row: dict, answer: str, bank: dict, attach_to: str = "") -> bool:
    #
    # The answer becomes a new entry in the free section of the bank, tagged
    # with the skill it answers. attach_to is a role id to show it under that
    # role, or "" for the free section. The skill is also added to the skills list
    # so it counts as listed next time. The caller saves the bank to disk.
    # The answered gap row is marked demonstrated by the new entry right here,
    # which is what a re-check would conclude anyway (the tagged skill
    # matches), so no second round of model calls is needed.
    # Returns False when the answer means "skip".
    #
    answer = answer.strip()
    if answer.lower().strip(" .!") in SKIP_ANSWERS:  # "no", "No.", "n/a"... mean skip, never a bullet
        return False
    new_id = next_free_id(bank)
    bank["free"].append({"id": new_id, "skill": row["requirement"], "text": answer, "attach_to": attach_to})
    row.update(status="demonstrated", bullet=new_id, evidence=answer, question="")
    known_skills = [skill.lower() for skill in bank["skills"]]
    if row["requirement"].lower() not in known_skills:
        bank["skills"].append(row["requirement"])
    return True


def ask_student(gaps: list[dict], bank: dict) -> int:
    added = 0
    print("\nAnswer honestly, or type 'no' (or press Enter) to skip. Answers are saved to the bank and go into the CV")
    print("exactly as you type them: write each as a finished CV sentence, starting with an action verb.")
    for row in gaps:
        if row["status"] == "demonstrated":
            continue
        if add_answer(row, input(f"\n{row['question']}\n> "), bank):
            added += 1
    return added

# ---------------------------------------------------------------------
# 5. SELECTION (plain Python: roles stay chronological)
# ---------------------------------------------------------------------
def select_bullets(bank: dict, gaps: list[dict], requirements: list[str], min_per_role: int = 2) -> list[dict]:
    weight = {r: len(requirements) - i for i, r in enumerate(requirements)}
    scores, matched = {}, {}
    for g in gaps:
        if g["bullet"]:
            factor = 1.0 if g["status"] == "demonstrated" else 0.5
            scores[g["bullet"]] = scores.get(g["bullet"], 0) + weight[g["requirement"]] * factor
            label = g["requirement"] if g["status"] == "demonstrated" else f"{g['requirement']} (partial)"
            matched.setdefault(g["bullet"], []).append(label)

    #
    # Free entries are only used when relevant (score > 0). One attached to a
    # role joins that role; the rest go to a closing "other experience" section.
    #
    free_bullets = [b for b in bank["free"] if scores.get(b["id"], 0) > 0]
    role_ids = {role["id"] for role in bank["roles"]}

    selected = []
    for role in bank["roles"]:
        ranked = sorted(role["bullets"], key=lambda b: -scores.get(b["id"], 0))
        keep = [b for b in ranked if scores.get(b["id"], 0) > 0]
        keep += [b for b in free_bullets if b["attach_to"] == role["id"]]
        keep.sort(key=lambda b: -scores.get(b["id"], 0))
        target = min(min_per_role, len(ranked))
        for b in ranked:
            if len(keep) >= target:
                break
            if b not in keep:
                keep.append(b)
        if keep:
            new_bullets = [dict(b, matched=matched.get(b["id"], [])) for b in keep]
            selected.append(dict(role, bullets=new_bullets))

    unattached = [b for b in free_bullets if b["attach_to"] not in role_ids]
    unattached.sort(key=lambda b: -scores.get(b["id"], 0))
    if unattached:
        new_bullets = [dict(b, matched=matched.get(b["id"], [])) for b in unattached]
        selected.append({"id": "free", "title": FREE_SECTION_TITLE, "company": "", "dates": "", "bullets": new_bullets})
    return selected

# ---------------------------------------------------------------------
# 6. CV OUTPUT
# ---------------------------------------------------------------------
def build_selection_rows(selected: list[dict], only_matched: bool) -> list[dict]:
    rows = []
    for role in selected:
        for b in role["bullets"]:
            if only_matched and not b["matched"]:
                continue
            rows.append({
                "role": role["title"],
                "bullet": b["text"],
                "matches": ", ".join(b["matched"]) or "(kept to fill the role)",
            })
    return rows


def build_cv(bank: dict, selected: list[dict], requirements: list[str], job: dict) -> str:
    reqs = [r.lower() for r in requirements]
    skills = sorted(bank["skills"],
                    key=lambda s: 0 if any(r in s.lower() or s.lower().split(" (")[0] in r for r in reqs) else 1)
    lines = [f"# {bank['name']}", f"{bank['email']} · {bank['location']}", "",
             "## Skills", " · ".join(skills), "", "## Experience", ""]
    for role in selected:
        header = f"### {role['title']}" + (f" - {role['company']}" if role["company"] else "")
        lines.append(header)
        if role["dates"]:
            lines.append(f"*{role['dates']}*")
        lines += [f"- {b['text']}" for b in role["bullets"]]  # verbatim from the bank
        lines.append("")
    lines += ["## Education"] + [f"- {e}" for e in bank["education"]]
    lines += ["", f"<!-- Tailored for: {job['title']} at {job['company']} -->"]
    return "\n".join(lines)

# ---------------------------------------------------------------------
# 7. RUN
# ---------------------------------------------------------------------
def write_log(log_name: str, content: str) -> None:
    #
    # One plain-text file per pipeline stage in LOG_DIR, overwritten on every
    # run, so the latest run can be inspected after the cell finishes.
    #
    LOG_DIR.mkdir(exist_ok=True)
    (LOG_DIR / f"{log_name}.txt").write_text(content, encoding="utf-8")


def main() -> None:
    print(f"Fetching jobs from: {', '.join(JOB_SOURCES)}...")
    jobs = fetch_jobs(JOB_SOURCES)
    results = search_jobs(jobs, SEARCH_KEYWORD)
    write_log("results", json.dumps(results, indent=2, ensure_ascii=False))
    if not results:
        print(f"No remote jobs match '{SEARCH_KEYWORD}'. Try a broader keyword.")
        return

    shown = results[:MAX_JOBS_SHOWN]
    for i, job in enumerate(shown):
        print(f"[{i}] {job['title']} - {job['company']} ({job['location']}, {job['source']})")
    choice = input("\nPick a job number: ").strip()
    job = shown[int(choice)] if choice.isdigit() and int(choice) < len(shown) else shown[0]
    job_text = job["description"]
    print(f"\nSelected: {job['title']} - {job['company']}\nSource: {job['url']} (via {job['source']})")
    print(job_text)

    print("\nExtracting requirements...")
    requirements = extract_requirements(job_text)
    write_log("requirements", "\n".join(requirements))
    if not requirements:
        print("The model couldn't extract requirements. Try another job.")
        return
    print("Requirements:", ", ".join(requirements))

    print("\nChecking the sentence bank against each requirement...")
    gaps = analyze_gaps(BANK, requirements)
    selected = select_bullets(BANK, gaps, requirements)

    relevant_rows = build_selection_rows(selected, True)
    print("\nFrom your bank, relevant to this job (used exactly as written):")
    if relevant_rows:
        display(pd.DataFrame(relevant_rows))
    else:
        print("(nothing in the bank matches this job's requirements)")

    open_gaps = [g for g in gaps if g["status"] != "demonstrated"]
    if open_gaps:
        print("\nNot yet shown by your bank:")
        display(pd.DataFrame(open_gaps)[["requirement", "status", "evidence"]])
    if ASK_STUDENT and open_gaps and ask_student(gaps, BANK):
        save_bank(BANK, BANK_PATH)
        print(f"\nSaved your answers to {BANK_PATH}.")
        selected = select_bullets(BANK, gaps, requirements)  # merge the answers into the selection
    write_log("gaps", json.dumps(gaps, indent=2, ensure_ascii=False))  # after answers, if any

    rows = build_selection_rows(selected, False)
    write_log("rows", json.dumps(rows, indent=2, ensure_ascii=False))

    cv = build_cv(BANK, selected, requirements, job)
    CV_MARKDOWN_PATH.write_text(cv, encoding="utf-8")
    write_log("cv", cv)
    markdown_to_pdf(cv, CV_PDF_PATH)
    display(Markdown(cv))
    #
    # google.colab is already in sys.modules inside a Colab kernel, so this
    # detects Colab without needing a try/except around the import.
    #
    if "google.colab" in sys.modules:
        from google.colab import files
        files.download(str(CV_MARKDOWN_PATH))
        files.download(str(CV_PDF_PATH))
    else:
        print(f"Saved {CV_MARKDOWN_PATH} and {CV_PDF_PATH}")


#
# In a Colab cell __name__ is also "__main__", so the cell still runs main().
# `streamlit run cv_project.py` lands here too: it gets the chat app in
# streamlit_app.py instead of questions asked in the terminal.
#
def running_in_streamlit() -> bool:
    if "streamlit" not in sys.modules:
        return False
    from streamlit.runtime.scriptrunner import get_script_run_ctx
    return get_script_run_ctx() is not None


if __name__ == "__main__":
    if running_in_streamlit():
        import runpy
        runpy.run_path(str(Path(__file__).with_name("streamlit_app.py")))
    else:
        main()